#!/usr/bin/env python3
"""
Round 128b (culprits-tiles-more), 2 October 2026. Upload after round125b_tiles.py.

- scripts/enforcement_registers.py (new): England's Environment Agency
  enforcement actions, Canada's Environmental Offenders Registry and the US
  EPA's enforcement cases, each as map tiles plus every field in its box.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/enforcement_registers.py': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
